namespace Workwise.Web.Models;
// Supporting entities for the Workwise domain. Authentication/session storage uses ASP.NET Core Identity.
public class SystemSetting { public long Id {get;set;} public string SettingKey {get;set;} = ""; public string SettingValue {get;set;} = ""; public long? UpdatedBy {get;set;} }
public class AuditLog { public long Id {get;set;} public long? ActorUserId {get;set;} public string Action {get;set;} = ""; public string EntityType {get;set;} = ""; public long? EntityId {get;set;} public string? OldValues {get;set;} public string? NewValues {get;set;} public DateTime CreatedAt {get;set;} = DateTime.UtcNow; }
public class TeamMember {  public long TeamId {get;set;} public long EmployeeUserId {get;set;} public DateTime JoinedAt {get;set;} = DateTime.UtcNow; public DateTime? LeftAt {get;set;} }
public class ProjectMember {  public long ProjectId {get;set;} public long UserId {get;set;} public string ProjectRole {get;set;} = "Member"; }
public class EmployeeAvailability { public long Id {get;set;} public long EmployeeUserId {get;set;} public DateTime StartsAt {get;set;} public DateTime EndsAt {get;set;} public string AvailabilityType {get;set;} = "Unavailable"; public string? Notes {get;set;} }
public class TaskDependency {  public long TaskId {get;set;} public long DependsOnTaskId {get;set;} public string DependencyType {get;set;} = "FinishToStart"; }
public class TaskComment { public long Id {get;set;} public long TaskId {get;set;} public long AuthorUserId {get;set;} public string Body {get;set;} = ""; public DateTime CreatedAt {get;set;} = DateTime.UtcNow; }
public class TaskAttachment { public long Id {get;set;} public long TaskId {get;set;} public long UploadedBy {get;set;} public string OriginalName {get;set;} = ""; public string StorageKey {get;set;} = ""; public string MimeType {get;set;} public long SizeBytes {get;set;} }
public class AllocationScore { public long Id {get;set;} public long TaskId {get;set;} public long EmployeeUserId {get;set;} decimal Score {get;set;} public string ScoreBreakdown {get;set;} = "{}"; public DateTime CalculatedAt {get;set;} = DateTime.UtcNow; }
public class AllocationHistory { public long Id {get;set;} public long TaskId {get;set;} public long SuggestedEmployeeId {get;set;} public long? SelectedEmployeeId {get;set;} public long? DecisionBy {get;set;} public string Decision {get;set;} = "Suggested"; public DateTime CreatedAt {get;set;} = DateTime.UtcNow; }
public class AllocationRule { public long Id {get;set;} public string Name {get;set;} = ""; public string RuleConfig {get;set;} = "{}"; public bool IsActive {get;set;} = true; public long? UpdatedBy {get;set;} }
public class WorkloadRecord { public long Id {get;set;} public long EmployeeUserId {get;set;} public DateTime PeriodStart {get;set;} public DateTime PeriodEnd {get;set;} public int CapacityMinutes {get;set;} public int AssignedMinutes {get;set;} }
public class TimeEntry { public long Id {get;set;} public long TaskId {get;set;} public long EmployeeUserId {get;set;} public DateTime StartedAt {get;set;} public DateTime? EndedAt {get;set;} public int DurationMinutes {get;set;} public string? Notes {get;set;} }
public class WorkSchedule { public long Id {get;set;} public long EmployeeUserId {get;set;} public int DayOfWeek {get;set;} public TimeSpan StartTime {get;set;} public TimeSpan EndTime {get;set;} public DateTime EffectiveFrom {get;set;} public DateTime? EffectiveTo {get;set;} }
public class NotificationPreference {  public long UserId {get;set;} public bool InAppEnabled {get;set;} = true; public bool EmailEnabled {get;set;} = true; public bool TaskUpdatesEnabled {get;set;} = true; public bool RemindersEnabled {get;set;} = true; }
